import { test, expect } from '@playwright/test';

test.describe('Virus Scan Status for Uploaded Files', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display virus scan status for uploaded file', async ({ page }) => {
    // Upload a file using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('fixtures/sample-document.pdf');

    // Verify file upload button is visible
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Click upload button
    await uploadButton.click();

    // Wait for upload to complete
    await page.waitForURL('**/file-upload/status');

    // Verify virus scan status is displayed
    const statusContainer = page.getByRole('region', { name: /virus scan status/i });
    await expect(statusContainer).toBeVisible();

    // Verify status message is present
    const statusMessage = page.getByText(/scanning.../i);
    await expect(statusMessage).toBeVisible();

    // Verify progress bar is visible
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Verify success message is visible
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify file name is displayed
    const fileName = page.getByText(/sample-document.pdf/i);
    await expect(fileName).toBeVisible();

    // Verify file size is displayed
    const fileSize = page.getByText(/1.2 MB/i);
    await expect(fileSize).toBeVisible();

    // Verify virus scan result
    const scanResult = page.getByText(/clean/i);
    await expect(scanResult).toBeVisible();

    // Verify download button is available
    const downloadButton = page.getByRole('button', { name: /download/i });
    await expect(downloadButton).toBeVisible();
  });

  test('should display error when file upload fails', async ({ page }) => {
    // Upload a corrupted file using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('fixtures/corrupted-file.pdf');

    // Verify error message is displayed
    const errorMessage = page.getByText(/file is corrupted/i);
    await expect(errorMessage).toBeVisible();

    // Verify upload button is disabled
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeDisabled();

    // Verify virus scan status is not displayed
    const statusContainer = page.getByRole('region', { name: /virus scan status/i });
    await expect(statusContainer).not.toBeVisible();

    // Verify file name is not displayed
    const fileName = page.getByText(/sample-document.pdf/i);
    await expect(fileName).not.toBeVisible();

    // Verify file size is not displayed
    const fileSize = page.getByText(/1.2 MB/i);
    await expect(fileSize).not.toBeVisible();

    // Verify success message is not visible
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Verify download button is not available
    const downloadButton = page.getByRole('button', { name: /download/i });
    await expect(downloadButton).not.toBeVisible();
  });
});
